// Reçoit le payload envoyé par le backend CleanMatch à la publication d'une mission
// (contrat détaillé dans n8n/README.md) et produit UN item par agent à notifier,
// avec le message Discord déjà formaté.
const SEUIL_SCORE = 70; // strictement supérieur, cf. cahier des charges

const entree = $input.first().json;
const payload = entree.body ?? entree; // le nœud Webhook (v2) range le corps dans "body"
const mission = payload.mission;
const agents = Array.isArray(payload.agents) ? payload.agents : [];

if (!mission || !mission.id || !mission.intitule) {
  throw new Error('Payload invalide : "mission.id" et "mission.intitule" sont obligatoires (voir n8n/README.md)');
}

// "2026-09-21" ou ISO complet -> "21/09/2026" (en UTC pour ne pas décaler les dates sans heure)
function formatDate(valeur) {
  if (!valeur) return '?';
  const d = new Date(valeur);
  if (Number.isNaN(d.getTime())) return String(valeur);
  const jj = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  return `${jj}/${mm}/${d.getUTCFullYear()}`;
}

const lieu = [mission.ville, mission.codePostal ? `(${mission.codePostal})` : ''].filter(Boolean).join(' ') || 'lieu non précisé';
const dates = `du ${formatDate(mission.dateDebut)} au ${formatDate(mission.dateFin)}`;
const creneau = mission.creneau || 'non précisé';
const remuneration = mission.remuneration != null
  ? `${Number(mission.remuneration).toFixed(2).replace('.', ',')} €/h brut`
  : 'non précisée';

const items = [];
for (const agent of agents) {
  const score = Number(agent.score);
  if (!Number.isFinite(score) || score <= SEUIL_SCORE) continue;

  // On n'affiche jamais l'e-mail dans le salon Discord (donnée personnelle) : prénom + nom suffisent.
  const nomAgent = [agent.prenom, agent.nom].filter(Boolean).join(' ') || 'Agent';

  const lignes = [
    `**Nouvelle mission pour ${nomAgent}** — compatibilité **${Math.round(score)}/100**`,
    `> **${mission.intitule}** — ${lieu}`,
    `> Dates : ${dates} · Créneau : ${creneau}`,
    `> Rémunération : ${remuneration}`,
  ];
  if (mission.url) lignes.push(`> Voir la mission : ${mission.url}`);
  lignes.push(`Mission n° ${mission.id} — postulez depuis votre espace CleanMatch.`);

  items.push({
    json: {
      missionId: mission.id,
      agentId: agent.id ?? null,
      score,
      message: lignes.join('\n'),
    },
  });
}

// Aucun agent au-dessus du seuil : on ne renvoie rien, la suite du workflow ne s'exécute pas.
return items;
